import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"米游币兑换网页","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/features/coin-shop.md","filePath":"projects/lotus-plugin/docs/features/coin-shop.md"}'),l={name:"projects/lotus-plugin/docs/features/coin-shop.md"};function p(t,s,o,h,r,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="米游币兑换网页" tabindex="-1">米游币兑换网页 <a class="header-anchor" href="#米游币兑换网页" aria-label="Permalink to &quot;米游币兑换网页&quot;">​</a></h1><p>独立网页管理商品与兑换预约，复用 Lotus 已绑定的 profile、Cookie 和设备信息。机器人只负责发放专属入口和通知兑换结果。</p><h2 id="打开页面" tabindex="-1">打开页面 <a class="header-anchor" href="#打开页面" aria-label="Permalink to &quot;打开页面&quot;">​</a></h2><p>私聊机器人发送 <code>#米游币兑换</code> 或 <code>#米游币商城</code>，打开返回的专属链接。链接 10 分钟内有效，只能使用一次；浏览器登录会话默认保留 8 小时。不要转发该链接。页面只允许查看和操作当前 QQ 自己的 profile，不向浏览器返回 Cookie、stoken 或设备凭据。</p><p>群里触发只会提示私聊，不在群内发布登录链接。机器人重启后需要重新获取登录链接，已有预约仍会恢复。</p><h2 id="浏览与预约" tabindex="-1">浏览与预约 <a class="header-anchor" href="#浏览与预约" aria-label="Permalink to &quot;浏览与预约&quot;">​</a></h2><ol><li>在页面顶部选择 profile，再选择游戏分区。</li><li>商品列表显示米游币价格、当前库存、下一批开放时间和数量。时间统一为北京时间，并显示倒计时；库存为零但官方有下一批时间时仍可预约。</li><li>打开商品详情，核对官方兑换条件；游戏奖励选择当前账号绑定的角色，实物商品选择米游社已有的收货地址。地址只显示脱敏姓名和手机号末四位。</li><li>勾选使用该 profile 的米游币兑换 1 件商品，再点击创建预约或立即兑换。</li><li>在“我的预约”查看状态、取消未提交的预约，或核对待确认结果。</li></ol><p>未选定商品、未创建预约时不会自动兑换。创建预约不预扣米游币；成功兑换时由官方扣除。真实兑换仍取决于官方库存、等级、限购及验证要求，页面显示的条件以商品详情为准。</p><h2 id="定时执行" tabindex="-1">定时执行 <a class="header-anchor" href="#定时执行" aria-label="Permalink to &quot;定时执行&quot;">​</a></h2><p>预约持久化保存在 <code>data/coinShop/plans.json</code>，不保存 Cookie 或设备凭据。到点前 15 秒检查登录态、设备、余额与兑换目标，随后等待目标时间提交。机器人的系统时钟需要正常同步。</p><p>同一账号的兑换按顺序执行，避免同一计划重复提交。重复预约同账号、同商品会被拒绝。价格或类型变化、绑定账号变化时停止，需重新预约；官方调整未来开放时间时会同步计划。错过原定场次超过 30 秒不补发请求，需重新预约。</p><p>官方明确返回未到兑换时间、系统繁忙等可重试结果时，在开放后 20 秒内每隔至少 500 毫秒尝试，最多 30 次；成功后立即停止。余额不足、限购、售罄和需要验证等结果停止执行，并通知发起者。</p><p>兑换提交后网络中断时，不能假定没有扣币，因此标记为“结果待确认”，不会自动重发。请先核对米游社兑换记录，再在页面确认“已兑换”或“未兑换”。机器人在请求提交过程中重启也按相同方式处理。</p><h2 id="共用端口与独立部署" tabindex="-1">共用端口与独立部署 <a class="header-anchor" href="#共用端口与独立部署" aria-label="Permalink to &quot;共用端口与独立部署&quot;">​</a></h2><p>全局配置的 <code>coin_shop</code> 字段：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">coin_shop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">auto</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18164</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/lotus/coin-shop</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  public_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  session_hours</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li><code>auto</code>：优先挂到 TRSS 的现有 HTTP 服务，不另占端口；没有共用服务时启用 <code>host</code>、<code>port</code> 指定的独立服务。</li><li><code>shared</code>：只使用 TRSS 的共用端口，不提供共用服务时明确报错。</li><li><code>standalone</code>：使用独立端口，便于单独反向代理。</li><li><code>path</code>：网页和 API 的挂载路径。</li><li><code>public_url</code>：本机配置中的外部访问地址，例如 <code>https://your-domain.example/lotus/coin-shop/</code>。留空时使用 TRSS 配置的地址或本机独立端口地址。域名和 frp 参数无需写入源码。</li></ul><p>共用模式下，网页自身完成登录鉴权，处理自己的路径后直接返回，避免登录票据和会话 Cookie 被宿主通用请求日志记录。其他 TRSS 路由保持原处理方式。请求会校验来源与 CSRF 凭据，Cookie 使用 HttpOnly、SameSite；公网应通过 HTTPS 访问。</p><h2 id="实现参考" tabindex="-1">实现参考 <a class="header-anchor" href="#实现参考" aria-label="Permalink to &quot;实现参考&quot;">​</a></h2><p>官方商城的商品、余额、地址和角色查询接口，以及商品兑换请求参数，参考了 <a href="https://github.com/Marchen-orz/MiyoQian/blob/master/miyouqian/tasks/shop_exchange.py" target="_blank" rel="noreferrer">MiyoQian 的商城实现</a>。Lotus 使用自身的登录、设备、网页鉴权、持久化预约与调度，不调用第三方兑换服务。</p>`,20)])])}const u=a(l,[["render",p]]);export{k as __pageData,u as default};
